sys_script_include.script:
var IncentIQOpportunityService = Class.create();
IncentIQOpportunityService.prototype = {

    initialize: function() {
        this.LOG = "IncentIQOpportunityService :: ";
        this.SAP_QUOTE_OBJECT_ID = 'b314ae5b33adc710dccb9c173e5c7bda';
    },

    getOpportunities: function() {

        var opportunities = [];

        var profileGR = new GlideRecordSecure('x_ctans_incentnow_user_profile');
        profileGR.addQuery('user', gs.getUserID());
        profileGR.setLimit(1);
        profileGR.query();

        if (!profileGR.next()) {
            return { found: false, message: "User not onboarded to IncentIQ", opportunities: [] };
        }

        var externalId = profileGR.getValue('external_user_id');

        if (!externalId) {
            return { found: true, message: "No external user ID on file", opportunities: [] };
        }

        var lakeGR = new GlideRecordSecure('x_ctans_incentnow_data_lake_master');
        lakeGR.addQuery('user_id', externalId);
        lakeGR.addQuery('data_model_object', this.SAP_QUOTE_OBJECT_ID);
        lakeGR.orderByDesc('transaction_date');
        lakeGR.query();

        while (lakeGR.next()) {
            opportunities.push({
                accountId: lakeGR.getValue('column_01'),
                orderId: lakeGR.getValue('column_02'),
                amount: parseFloat(lakeGR.getValue('column_61')) || 0,
                date: lakeGR.getValue('transaction_date')
            });
        }

        return {
            found: true,
            opportunityCount: opportunities.length,
            opportunities: opportunities
        };
    },

    type: 'IncentIQOpportunityService'
};
